-- G25: bounded provisional serving, immutable session versions, and rollback.
create table public.content_serving_policies(id uuid primary key default gen_random_uuid(),policy_key text not null,version integer not null check(version>0),exposure_cap integer not null check(exposure_cap>0),cohort_percent integer not null check(cohort_percent between 1 and 100),minimum_promotion_exposures integer not null check(minimum_promotion_exposures>0),minimum_completion_rate numeric not null check(minimum_completion_rate between 0 and 1),maximum_issue_rate numeric not null check(maximum_issue_rate between 0 and 1),kill_switch boolean not null default false,active boolean not null default false,created_at timestamptz not null default now(),unique(policy_key,version));
insert into public.content_serving_policies(policy_key,version,exposure_cap,cohort_percent,minimum_promotion_exposures,minimum_completion_rate,maximum_issue_rate,active) values('default_provisional',1,100,10,50,.7,.05,true);
create table public.generated_content_serving_versions(id uuid primary key default gen_random_uuid(),candidate_id uuid not null unique references public.contract_generation_candidates(id) on delete restrict,text_version_id uuid unique references public.text_versions(id) on delete restrict,policy_id uuid not null references public.content_serving_policies(id) on delete restrict,state text not null check(state in('eligible_provisional','empirically_validated','trusted_reusable','withdrawn','retired')),payload_checksum text not null,immutable_payload jsonb not null,exposure_count integer not null default 0 check(exposure_count>=0),promoted_at timestamptz,withdrawn_at timestamptz,retired_at timestamptz,created_at timestamptz not null default now());
create table public.generated_content_serving_sessions(id uuid primary key default gen_random_uuid(),serving_version_id uuid not null references public.generated_content_serving_versions(id) on delete restrict,student_id uuid not null references public.students(id) on delete cascade,payload_checksum text not null,state_at_start text not null,cohort_bucket integer not null check(cohort_bucket between 0 and 99),started_at timestamptz not null default now(),completed_at timestamptz,unique(serving_version_id,student_id,started_at));
create table public.content_serving_state_events(id uuid primary key default gen_random_uuid(),serving_version_id uuid not null references public.generated_content_serving_versions(id) on delete restrict,from_state text,to_state text not null,event_type text not null check(event_type in('provisioned','promoted','withdrawn','retired','kill_switch_enabled','kill_switch_disabled')),reason text not null,evidence_snapshot jsonb not null default '{}',actor_profile_id uuid references public.profiles(id) on delete set null,created_at timestamptz not null default now());
create or replace function public.prevent_serving_payload_mutation()returns trigger language plpgsql as $$begin if old.immutable_payload<>new.immutable_payload or old.payload_checksum<>new.payload_checksum or old.candidate_id<>new.candidate_id then raise exception 'serving_version_is_immutable';end if;return new;end$$;create trigger immutable_serving_version before update on public.generated_content_serving_versions for each row execute function public.prevent_serving_payload_mutation();
create or replace function public.start_generated_content_session(p_serving_version_id uuid,p_student_id uuid)returns uuid language plpgsql security definer set search_path=public as $$declare v public.generated_content_serving_versions;pol public.content_serving_policies;b integer;s uuid;begin if auth.role()<>'service_role' and not public.owns_student(p_student_id) then raise exception 'forbidden';end if;select * into v from public.generated_content_serving_versions where id=p_serving_version_id for update;if not found or v.state in('withdrawn','retired') then raise exception 'not_serving';end if;select * into pol from public.content_serving_policies where id=v.policy_id;if pol.kill_switch then raise exception 'kill_switch';end if;b:=mod(abs(hashtextextended(p_student_id::text||':'||v.id::text,0)),100);if v.state='eligible_provisional' and (v.exposure_count>=pol.exposure_cap or b>=pol.cohort_percent) then raise exception 'provisional_limit';end if;insert into public.generated_content_serving_sessions(serving_version_id,student_id,payload_checksum,state_at_start,cohort_bucket)values(v.id,p_student_id,v.payload_checksum,v.state,b)returning id into s;update public.generated_content_serving_versions set exposure_count=exposure_count+1 where id=v.id;return s;end$$;
revoke all on function public.start_generated_content_session(uuid,uuid) from public;grant execute on function public.start_generated_content_session(uuid,uuid) to authenticated,service_role;
alter table public.content_serving_policies enable row level security;alter table public.generated_content_serving_versions enable row level security;alter table public.generated_content_serving_sessions enable row level security;alter table public.content_serving_state_events enable row level security;create policy serving_policy_read on public.content_serving_policies for select using(active or public.is_platform_admin());create policy serving_versions_read on public.generated_content_serving_versions for select using(state in('eligible_provisional','empirically_validated','trusted_reusable') or public.is_staff());create policy serving_sessions_read on public.generated_content_serving_sessions for select using(public.can_view_student(student_id));create policy serving_events_staff_read on public.content_serving_state_events for select using(public.is_staff());grant select on public.content_serving_policies,public.generated_content_serving_versions,public.generated_content_serving_sessions,public.content_serving_state_events to authenticated;
